// Local Variables:
// verilog-library-directories:("." "../../emmu/hdl" "../../memory/hdl" "../../edma/hdl/")
// End:

module etx_io (/*AUTOARG*/
   // Outputs
   txo_lclk_p, txo_lclk_n, txo_frame_p, txo_frame_n, txo_data_p,
   txo_data_n, tx_wr_wait, tx_rd_wait,
   // Inputs
   tx_lclk_io, tx_lclk_div4, tx_lclk90, txi_wr_wait_p, txi_wr_wait_n,
   txi_rd_wait_p, txi_rd_wait_n, tx_data_slow, tx_frame_slow
   );

   parameter PLATFORM    = `CFG_PLATFORM;   
   parameter IOSTD_ELINK = "LVDS_25";
   parameter PW          = 104;
   parameter ETYPE       = 0; // 0 = parallella
                              // 1 = ephycard     
   //###########
   //# reset, clocks
   //##########
   input 	tx_lclk_io;	     //fast ODDR
   input 	tx_lclk_div4;	     //slow clock
   input 	tx_lclk90;           //fast 90deg shifted lclk   

   //###########
   //# eLink pins
   //###########
   output 	txo_lclk_p,   txo_lclk_n;     // tx clock output
   output 	txo_frame_p, txo_frame_n;     // tx frame signal
   output [7:0] txo_data_p, txo_data_n;       // tx data (dual data rate)
   input 	txi_wr_wait_p,txi_wr_wait_n;  // tx write pushback
   input 	txi_rd_wait_p, txi_rd_wait_n; // tx read pushback

   //#############
   //# Fabric interface
   //#############
   input [63:0]   tx_data_slow;    //data for burst or transaction
   input  [3:0]   tx_frame_slow;   //framing signal
   output 	  tx_wr_wait;
   output 	  tx_rd_wait;

   //############
   //# REGS
   //############
   reg [63:0] 	  tx_data;
   reg [3:0] 	  tx_frame;
   wire [15:0] 	  tx_data16;
   wire  	  tx_frame16;
   reg 		  tx_wr_wait_sync;
   reg 		  tx_rd_wait_sync; 
   reg 		  tx_wr_wait_reg;
   reg 		  tx_rd_wait_reg;
   reg 		  tx_wr_wait_reg2;
   reg 		  tx_rd_wait_reg2;
   //############
   //# WIRES
   //############
   wire [15:0] 	  tx_data_mux;   
   wire 	  txo_frame_ddr;
   wire 	  txo_lclk90;   
   wire 	  tx_wr_wait_async;
   wire 	  tx_rd_wait_async;
   wire [7:0] 	  txo_data_ddr;
   wire 	  invert_pins;

   //#########################################
   //# Pins inverted for 64-core board
   //#########################################        
`ifdef TARGET_E64
   assign invert_pins=1'b1;
`else
   assign invert_pins=1'b0;
`endif
   //#########################################
   //# Synchronizatsion to fast domain
   //#########################################        

   //Find the aligned edge
   oh_edgealign edgealign0 (.firstedge	(firstedge),
  			    .fastclk	(tx_lclk_io),
			    .slowclk	(tx_lclk_div4)
			   );

   //Data shift registers
   always @ (posedge tx_lclk_io)
     if(firstedge) //"load"
       begin
	  tx_data[63:0]   <= tx_data_slow[63:0]; //changes every 4 cycles
	  tx_frame[3:0]   <= tx_frame_slow[3:0];	
       end
     else //"shift"
       begin
	  tx_data[63:0]   <= {16'b0,tx_data[63:16]};
	  tx_frame[3:0]   <= {tx_frame[2:0],1'b0};	  
       end

   assign tx_data16[15:0] = tx_data[15:0];   
   assign tx_frame16      = tx_frame[3];

   //##############################################
   //# Wait signal synchronization
   //############################################## 
   always @ (negedge tx_lclk_io)
     begin
	tx_wr_wait_sync <= tx_wr_wait_async ^ invert_pins;
	tx_rd_wait_sync <= tx_rd_wait_async ^ invert_pins;
     end

   //Looks like legacy elink puts out short wait pulses.
   //Let's make sure they don't sneak through

   always @ (posedge tx_lclk_div4)
     begin
	tx_wr_wait_reg  <= tx_wr_wait_sync; 
	tx_wr_wait_reg2 <= tx_wr_wait_reg;
	tx_rd_wait_reg  <= tx_rd_wait_sync;
	tx_rd_wait_reg2 <= tx_rd_wait_reg;	
     end
   assign tx_wr_wait = tx_wr_wait_reg | tx_wr_wait_reg2;
   assign tx_rd_wait = tx_rd_wait_reg | tx_rd_wait_reg2;

   //############################################
   //# IO DRIVER STUFF
   //############################################  
   generate
      genvar i;
      if(PLATFORM=="ULTRASCALE")
	begin : ultrascale
	   //DATA
	   for(i=0; i<8; i=i+1)
	     begin : gen_oddr
		ODDRE1 oddr_data (.Q  (txo_data_ddr[i]),
				  .C  (tx_lclk_io),
				  .D1 (tx_data16[i+8] ^ invert_pins),
				  .D2 (tx_data16[i] ^ invert_pins));
	     end
	   //FRAME
	   ODDRE1 oddr_frame (.Q  (txo_frame_ddr),
			 .C  (tx_lclk_io),
			 .D1 (tx_frame16 ^ invert_pins),
			 .D2 (tx_frame16 ^ invert_pins));

	   //LCLK
	   ODDRE1 oddr_lclk (.Q  (txo_lclk90),
			     .C  (tx_lclk90),
			     .D1 (1'b1 ^ invert_pins),
			     .D2 (1'b0 ^ invert_pins));
	end // block: ultrascale
      else
	begin : zynq
	   for(i=0; i<8; i=i+1)
	     begin : gen_oddr
		ODDR #(.DDR_CLK_EDGE  ("SAME_EDGE"))
		oddr_data (
			   .Q  (txo_data_ddr[i]),
			   .C  (tx_lclk_io),
			   .CE (1'b1),
			   .D1 (tx_data16[i+8] ^ invert_pins),
			   .D2 (tx_data16[i] ^ invert_pins),
			   .R  (1'b0),
			   .S  (1'b0)
			   );
	     end
	   //FRAME
	   ODDR #(.DDR_CLK_EDGE  ("SAME_EDGE"))
	   oddr_frame (
		       .Q  (txo_frame_ddr),
		       .C  (tx_lclk_io),
		       .CE (1'b1),
		       .D1 (tx_frame16 ^ invert_pins),
		       .D2 (tx_frame16 ^ invert_pins),
		       .R  (1'b0), //reset
		       .S  (1'b0)
		       );

	   //LCLK
	   ODDR #(.DDR_CLK_EDGE  ("SAME_EDGE"))
	   oddr_lclk (
		      .Q  (txo_lclk90),
		      .C  (tx_lclk90),
		      .CE (1'b1),
		      .D1 (1'b1 ^ invert_pins),
		      .D2 (1'b0 ^ invert_pins),
		      .R  (1'b0),//should be no reason to reset clock, static input
		      .S  (1'b0)
		      );
	end

	endgenerate

   //Buffer drivers
   OBUFDS obufds_data[7:0] (.O   (txo_data_p[7:0]),
			    .OB  (txo_data_n[7:0]),
			    .I   (txo_data_ddr[7:0]));

   OBUFDS obufds_frame (.O   (txo_frame_p),
			.OB  (txo_frame_n),
			.I   (txo_frame_ddr));

   OBUFDS obufds_lclk (.O   (txo_lclk_p),
		       .OB  (txo_lclk_n),
		       .I   (txo_lclk90));
   //Wait inputs
   generate
      if(ETYPE==1)
	begin
	   assign tx_wr_wait_async = txi_wr_wait_p;
	end
      else if (ETYPE==0)
	begin
	   IBUFDS
	     #(.DIFF_TERM  ("TRUE"),     // Differential termination
	       .IOSTANDARD (IOSTD_ELINK))
	   ibufds_wrwait
	     (.I     (txi_wr_wait_p),
	      .IB    (txi_wr_wait_n),
	      .O     (tx_wr_wait_async));	 
	end
   endgenerate

//TODO: Come up with cleaner defines for this
`define ZYNQMP
`ifdef ZYNQMP
  IBUFDS
     #(.DIFF_TERM  ("TRUE"),     // Differential termination
       .IOSTANDARD (IOSTD_ELINK))
      ibufds_rdwait
     (.I     (txi_rd_wait_p),
      .IB    (txi_rd_wait_n),
      .O     (tx_rd_wait_async));
`else
   //On Parallella this signal comes in single-ended
   assign tx_rd_wait_async = txi_rd_wait_p;
`endif

endmodule // etx_io
// Local Variables:
// verilog-library-directories:("." "../../emesh/hdl" "../../common/hdl")
// End:

`include "elink_constants.vh"
module etx_clocks (/*AUTOARG*/
   // Outputs
   tx_lclk_io, tx_lclk90, tx_lclk_div4, cclk_p, cclk_n, etx_nreset,
   etx_io_nreset, chip_nreset, tx_active,
   // Inputs
   sys_nreset, soft_reset, sys_clk
   );

   //Frequency Settings (Mhz)
   parameter FREQ_SYSCLK     = 100; 
   parameter FREQ_TXCLK      = 300;  
   parameter FREQ_CCLK       = 600;  
   parameter TXCLK_PHASE     = 90;   //txclk phase shift
   parameter TARGET          = `CFG_TARGET; // "XILINX", "ALTERA" etc
   parameter PLATFORM        = `CFG_PLATFORM;

   //Override reset counter size for simulation
`ifdef TARGET_SIM
   parameter RCW                 = 4;          // reset counter width
`else
   parameter RCW                 = 8;          // reset counter width
`endif


   //Don't touch these! (derived parameters)
   parameter          MMCM_VCO_MULT = 12;  //TX + CCLK
   localparam real    SYSCLK_PERIOD = 1000.000000 / FREQ_SYSCLK;
   localparam integer TXCLK_DIVIDE  = MMCM_VCO_MULT * FREQ_SYSCLK / FREQ_TXCLK;
   localparam integer CCLK_DIVIDE   = MMCM_VCO_MULT * FREQ_SYSCLK / FREQ_CCLK;

   //Input clock, reset, config interface
   input      sys_nreset;        // por reset (hw)
   input      soft_reset;        // rx enable signal (sw)

   //Main input clocks
   input      sys_clk;            // always on input clk cclk/TX MMCM

   //TX Clocks
   output     tx_lclk_io;        // tx clock for high speeed IO
   output     tx_lclk90;         // tx output clock shifted by 90 degrees
   output     tx_lclk_div4;      // tx slow clock for logic

   //Epiphany "free running" clock
   output     cclk_p, cclk_n;

   //Reset
   output     etx_nreset;        // reset for tx core logic
   output     etx_io_nreset;     // io reset (synced to high speed clock)
   output     chip_nreset;       // reset fpr Epiphany chip
   output     tx_active;         // enable for rx path (ensures active clock)

   //############
   //# WIRES
   //############

   //CCLK
   wire       cclk_reset;
   wire       cclk_mmcm;
   wire       cclk_bufio;
   wire       cclk_oddr;

   //TX
   wire       tx_lclk_mmcm;
   wire       tx_lclk90_mmcm;
   wire       tx_lckl_div4_mmcm;

   //MMCM & PLL
   wire       cclk_fb;
   //wire       cclk_fb_out;
   wire       lclk_fb_i;
   wire       pll_reset;
   wire       mmcm_locked;
   reg 	      mmcm_locked_reg;
   reg 	      mmcm_locked_sync;
   wire       lclk_locked;   
   wire       tx_nreset;
   wire       mmcm_reset;
   wire       tx_lclk_div4_mmcm;

   //###########################
   // RESET STATE MACHINE
   //###########################

   reg [RCW:0] reset_counter = 'b0; //works b/c of free running counter!
   reg 	       heartbeat;   
   reg [2:0]   reset_state;
   reg [1:0]   reset_pipe_lclkb;    
   reg [1:0]   reset_pipe_lclk_div4b;   

   //wrap around counter that generates a 1 cycle heartbeat       
   //free running counter...
   always @ (posedge sys_clk)
     begin
	reset_counter[RCW-1:0] <= reset_counter[RCW-1:0]+1'b1;
	heartbeat              <= ~(|reset_counter[RCW-1:0]);
     end

   //two clock synchronizer
   always @ (posedge sys_clk)
     begin
	mmcm_locked_reg   <= mmcm_locked;
	mmcm_locked_sync  <= mmcm_locked_reg;	
     end

`define TX_RESET_ALL        3'b000
`define TX_START_CCLK       3'b001
`define TX_STOP_CCLK        3'b010
`define TX_DEASSERT_RESET   3'b011
`define TX_HOLD_IT          3'b100 //???
`define TX_ACTIVE           3'b101

   //Reset sequence state machine      
   always @ (posedge sys_clk or negedge sys_nreset)
     if(!sys_nreset)
       reset_state[2:0]        <= `TX_RESET_ALL;   
     else if(heartbeat)
       case(reset_state[2:0])
	 `TX_RESET_ALL :
	   if(~soft_reset)
	     reset_state[2:0]  <= `TX_START_CCLK;	 
	 `TX_START_CCLK :
	   if(mmcm_locked_sync)
	     reset_state[2:0]  <= `TX_STOP_CCLK; 
	 `TX_STOP_CCLK :
	   reset_state[2:0]    <= `TX_DEASSERT_RESET;
	 `TX_DEASSERT_RESET :
	   reset_state[2:0]    <= `TX_HOLD_IT;
	 `TX_HOLD_IT :
	   if(mmcm_locked_sync)
	     reset_state[2:0]  <= `TX_ACTIVE;
	 `TX_ACTIVE:
	   if(soft_reset)
	     reset_state[2:0]    <= `TX_RESET_ALL; //stay there until nex reset

       endcase // case (reset_state[2:0])

   //reset mmcm (async)
   assign mmcm_reset =  (reset_state[2:0]==`TX_RESET_ALL)      |
			(reset_state[2:0]==`TX_STOP_CCLK)      |  
			(reset_state[2:0]==`TX_DEASSERT_RESET)
			;

   //reset chip (active low)
   assign chip_nreset  = (reset_state[2:0]==`TX_DEASSERT_RESET) |
		         (reset_state[2:0]==`TX_HOLD_IT)        |
		         (reset_state[2:0]==`TX_ACTIVE);   

   //reset the elink
   assign tx_nreset      =  ~(reset_state[2:0] != `TX_ACTIVE);


   assign tx_active   =  (reset_state[2:0] == `TX_ACTIVE);

   //#############################
   //#RESET SYNCING
   //#############################

   oh_rsync rsync_io (// Outputs
		   .nrst_out		(etx_io_nreset),
		   // Inputs
		   .clk			(tx_lclk_io),
		   .nrst_in		(tx_nreset));

   oh_rsync rsync_core (// Outputs
		     .nrst_out		(etx_nreset),
		     // Inputs
		     .clk		(tx_lclk_div4),
		     .nrst_in		(tx_nreset));


  generate
      if(TARGET=="XILINX")
	begin
	   //###########################
	   // MMCM FOR TXCLK + CCLK
	   //###########################
	   MMCME2_ADV
	     #(
	       .BANDWIDTH("OPTIMIZED"),          
	       .CLKFBOUT_MULT_F(MMCM_VCO_MULT),
	       .CLKFBOUT_PHASE(0.0),
	       .CLKIN1_PERIOD(SYSCLK_PERIOD),   
	       .CLKOUT0_DIVIDE_F(CCLK_DIVIDE),   //cclk_c
	       .CLKOUT1_DIVIDE(TXCLK_DIVIDE),    //tx_lclk
	       .CLKOUT2_DIVIDE(TXCLK_DIVIDE),    //tx_lclk90
	       .CLKOUT3_DIVIDE(TXCLK_DIVIDE*4),  //tx_lclk_div4
	       .CLKOUT4_DIVIDE(128),             //N/A
	       .CLKOUT5_DIVIDE(128),             //N/A
	       .CLKOUT6_DIVIDE(128),             //N/A
	       .CLKOUT0_DUTY_CYCLE(0.5),         
	       .CLKOUT1_DUTY_CYCLE(0.5),
	       .CLKOUT2_DUTY_CYCLE(0.5),
	       .CLKOUT3_DUTY_CYCLE(0.5),
	       .CLKOUT4_DUTY_CYCLE(0.5),
	       .CLKOUT5_DUTY_CYCLE(0.5),
	       .CLKOUT6_DUTY_CYCLE(0.5),
	       .CLKOUT0_PHASE(0.0),
	       .CLKOUT1_PHASE(0.0),
	       .CLKOUT2_PHASE(TXCLK_PHASE),
	       .CLKOUT3_PHASE(0.0),
	       .CLKOUT4_PHASE(0.0),
	       .CLKOUT5_PHASE(0.0),
	       .CLKOUT6_PHASE(0.0),
	       .DIVCLK_DIVIDE(1.0), 
	       .REF_JITTER1(0.01), 
	       .STARTUP_WAIT("FALSE") 
	       ) mmcm_cclk
	       (
		.CLKOUT0(cclk_mmcm),
		.CLKOUT0B(),
		.CLKOUT1(tx_lclk_mmcm),
		.CLKOUT1B(),
		.CLKOUT2(tx_lclk90_mmcm),//goes directly to IO
		.CLKOUT2B(),
		.CLKOUT3(tx_lclk_div4_mmcm),
		.CLKOUT3B(),
		.CLKOUT4(),
		.CLKOUT5(),
		.CLKOUT6(),
		.PWRDWN(1'b0),
		.RST(mmcm_reset),     //reset
		.CLKFBIN(cclk_fb),
		.CLKFBOUT(cclk_fb),  //feedback clock
		.CLKFBOUTB(),        //inverted output feedback clock     
		.CLKIN1(sys_clk),    //input clock
		.CLKIN2(1'b0),
		.CLKINSEL(1'b1),      
		.DADDR(7'b0),
		.DCLK(1'b0),
		.DEN(1'b0),
		.DI(16'b0),
		.DWE(1'b0),
		.DRDY(),
		.DO(), 
		.LOCKED(mmcm_locked), //locked indicator
		.PSCLK(1'b0),
		.PSEN(1'b0),
		.PSDONE(),
		.PSINCDEC(1'b0),
		.CLKFBSTOPPED(),
		.CLKINSTOPPED()
		);

	   //Tx clock buffers
	   BUFG i_lclk_bufg      (.I(tx_lclk_mmcm),     .O(tx_lclk_io));   //300MHz
	   BUFG i_lclk_div4_bufg (.I(tx_lclk_div4_mmcm),.O(tx_lclk_div4)); //75MHz
	   BUFG i_lclk90_bufg    (.I(tx_lclk90_mmcm),   .O(tx_lclk90));    //300MHz 90deg clock
	   //   BUFG i_fb_buf           (.I(cclk_fb_out), .O(cclk_fb_in));    //FB

	   //###########################
	   // CCLK
	   //###########################

	   //CCLK bufio
	   BUFIO bufio_cclk(.O(cclk_bufio), .I(cclk_mmcm));

	   //CCLK oddr 
	   if(PLATFORM=="ULTRASCALE")
	     begin : gen_ultrascale
		ODDRE1 oddr_lclk (
				  .Q  (cclk_oddr),
				  .C  (cclk_bufio),
				  .D1 (1'b1),
				  .D2 (1'b0));
	     end
	   else
	     begin : gen_zynq
		ODDR #(.DDR_CLK_EDGE  ("SAME_EDGE"), .SRTYPE("ASYNC"))
		oddr_lclk (
			   .Q  (cclk_oddr),
			   .C  (cclk_bufio),
			   .CE (1'b1),
			   .D1 (1'b1),
			   .D2 (1'b0),
			   .R  (1'b0),
			   .S  (1'b0));	
	     end

	   //CCLK differential buffer
	   OBUFDS  cclk_obuf (.O   (cclk_p),
			      .OB  (cclk_n),
			      .I   (cclk_oddr)
			      );

	end // if (TARGET=="XILINX")
      else
	begin
	   assign cclk_p       = sys_clk;
	   assign cclk_n       = sys_clk;
	   assign tx_lclk_io   = sys_clk;
	   assign tx_lclk_div4 = sys_clk;
	   assign tx_lclk90    = sys_clk;
	end
  endgenerate

