//#############################################################################
//# Function: Aligns positive edge of slow clock to fast clock                #
//#           !!!Assumes clocks are aligned and synchronous!!!                #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        # 
//#############################################################################
/*
 *    ___________             ___________
 * __/           \___________/           \   SLOWCLK
 *    __    __    __    __    __    __ 
 *  _/  \__/  \__/  \__/  \__/  \__/  \__/   FASTCLK
 *        ___________              _________   
 *    ___/ 1     1   \_0_____0____/          CLK45
 *           ____________              ___   
 *    ______/    1     1 \___0____0___/      CLK90 
 * 
 * ____                  ______               
 *     \________________/      \________     FIRSTEDGE 
 * 
 */
module oh_edgealign (/*AUTOARG*/
   // Outputs
   firstedge,
   // Inputs
   fastclk, slowclk
   );

   input  fastclk;
   input  slowclk;
   output firstedge;

   reg 	  clk45;
   reg 	  clk90;
   reg 	  firstedge;

   always @ (negedge fastclk) 
     clk45     <= slowclk;

   always @ (posedge fastclk) 
     begin
	clk90     <= clk45;
	firstedge <= ~clk45 & clk90;
     end

endmodule // oh_edgealign

module etx_remap (/*AUTOARG*/
   // Outputs
   emesh_access_out, emesh_packet_out,
   // Inputs
   clk, nreset, emesh_access_in, emesh_packet_in, remap_en, etx_wait
   );

   parameter AW = 32;
   parameter DW = 32;
   parameter PW = 104;

   //Clock
   input          clk;
   input 	  nreset;

   //Input from arbiter
   input          emesh_access_in;
   input [PW-1:0] emesh_packet_in;
   input 	  remap_en;             //enable tx remap (static)

   //Output to TX IO   
   output 	   emesh_access_out;
   output [PW-1:0] emesh_packet_out;

   //Wait signals from protocol block
   input 	   etx_wait;

   wire [31:0] 	   addr_in;
   wire [31:0] 	   addr_remap;
   wire [31:0] 	   addr_out;
   wire 	   write_in;

   reg 		   emesh_access_out;
   reg [PW-1:0]    emesh_packet_out;

   packet2emesh #(.AW(AW))
   p2e (// Outputs
	.write_in	(write_in),
	.datamode_in	(),
	.ctrlmode_in	(),
	.data_in	(),
	.dstaddr_in	(addr_in[31:0]),
	.srcaddr_in	(),
	// Inputs
	.packet_in	(emesh_packet_in[PW-1:0]));

   assign addr_remap[31:0] = {addr_in[29:18],         //ID
			      addr_in[17:16],         //SPECIAL GROUP
                             {(2){(|addr_in[17:16])}},//ZERO IF NOT SPECIAL
			     addr_in[15:0]
			     };


   assign addr_out[31:0] = remap_en ? addr_remap[31:0] :
                	              addr_in[31:0];


   //stall read/write access appropriately
   always @ (posedge clk)
     if(!nreset)
       emesh_access_out    <= 1'b0;
     else if(~etx_wait)
       emesh_access_out  <= emesh_access_in;

   always @ (posedge clk)     
     if(~etx_wait)
       emesh_packet_out[PW-1:0] <= {emesh_packet_in[PW-1:40],
				    addr_out[31:0],
				    emesh_packet_in[7:0]
				   };	   
endmodule // etx_remap


